// src/pages/History.js
import { useState, useEffect, useCallback, useRef } from 'react';
import { runsAPI, targetsAPI } from '../services/api';
import { Badge, Btn, DestIcons, toast } from '../components/UI';
import { useWS, useWSMessages } from '../context/WSContext';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { format } from 'date-fns';

function fmtBytes(b) {
  if (!b || b === 0) return '0 B';
  const u = ['B','KB','MB','GB'];
  const i = Math.floor(Math.log(Math.max(b,1)) / Math.log(1024));
  return (b / Math.pow(1024, i)).toFixed(1) + ' ' + u[i];
}

// ── RUN HISTORY ──────────────────────────────────────────────────────────────
export function HistoryPage() {
  const [runs,    setRuns]    = useState([]);
  const [targets, setTargets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState({ date:'', target_id:'', status:'' });
  const navigate = useNavigate();

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const f = {};
      if (filters.date)      f.date      = filters.date;
      if (filters.target_id) f.target_id = filters.target_id;
      if (filters.status)    f.status    = filters.status;
      const [r, t] = await Promise.all([runsAPI.list({ ...f, limit:100 }), targetsAPI.list()]);
      setRuns(r); setTargets(t);
    } catch(e) { toast(e.message, 'error'); }
    finally { setLoading(false); }
  }, [filters]);

  useEffect(() => { load(); }, [load]);

  const counts = {
    total:   runs.length,
    success: runs.filter(r=>r.status==='success').length,
    failed:  runs.filter(r=>r.status==='failed').length,
    partial: runs.filter(r=>r.status==='partial').length,
    running: runs.filter(r=>r.status==='running').length,
  };

  const pill = (bg, color, text) => (
    <span style={{ fontSize:11, fontWeight:700, padding:'4px 12px', borderRadius:20, background:bg, color }}>{text}</span>
  );

  const th = { textAlign:'left', fontSize:10, fontWeight:600, color:'#6e7681',
    letterSpacing:'.07em', textTransform:'uppercase', padding:'8px 12px',
    borderBottom:'1px solid #30363d', whiteSpace:'nowrap' };
  const td = (extra={}) => ({ padding:'9px 12px', borderBottom:'1px solid #21262d', fontSize:12, color:'#e6edf3', ...extra });

  return (
    <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>
      <div style={{ padding:'18px 24px 14px', borderBottom:'1px solid #30363d', background:'#161b22',
        display:'flex', justifyContent:'space-between', alignItems:'flex-start', flexShrink:0 }}>
        <div>
          <div style={{ fontSize:20, fontWeight:500, color:'#e6edf3' }}>Run History</div>
          <div style={{ fontSize:12, color:'#8b949e', marginTop:3 }}>
            {counts.total} runs · <span style={{ color:'#3fb950' }}>
              {counts.total > 0 ? Math.round(counts.success/counts.total*100) : 100}% success rate
            </span>
          </div>
        </div>
        <Btn variant="ghost" icon="refresh" onClick={load}>Refresh</Btn>
      </div>

      <div style={{ flex:1, overflowY:'auto', padding:'20px 24px', display:'flex', flexDirection:'column', gap:14 }}>
        {/* Filters */}
        <div style={{ background:'#161b22', border:'1px solid #30363d', borderRadius:12,
          padding:'12px 16px', display:'flex', gap:12, flexWrap:'wrap', alignItems:'center' }}>
          <span style={{ fontSize:11, color:'#6e7681', fontWeight:600 }}>Filter by date</span>
          <input type="date" value={filters.date}
            onChange={e=>setFilters(p=>({...p,date:e.target.value}))}
            style={{ fontSize:12, background:'#21262d', border:'1px solid #444c56',
              color:'#e6edf3', borderRadius:8, padding:'6px 10px' }}/>
          <span style={{ fontSize:11, color:'#6e7681', fontWeight:600 }}>Target</span>
          <select value={filters.target_id}
            onChange={e=>setFilters(p=>({...p,target_id:e.target.value}))}
            style={{ fontSize:12, background:'#21262d', border:'1px solid #444c56',
              color:'#e6edf3', borderRadius:8, padding:'6px 10px' }}>
            <option value="">All Targets</option>
            {targets.map(t=><option key={t.id} value={t.id}>{t.name}</option>)}
          </select>
          <span style={{ fontSize:11, color:'#6e7681', fontWeight:600 }}>Status</span>
          <select value={filters.status}
            onChange={e=>setFilters(p=>({...p,status:e.target.value}))}
            style={{ fontSize:12, background:'#21262d', border:'1px solid #444c56',
              color:'#e6edf3', borderRadius:8, padding:'6px 10px' }}>
            <option value="">All Statuses</option>
            {['success','failed','partial','running','pending'].map(s=><option key={s} value={s}>{s}</option>)}
          </select>
          <Btn variant="ghost" size="sm" onClick={()=>setFilters({date:'',target_id:'',status:''})}>Clear</Btn>
        </div>

        {/* Summary pills */}
        <div style={{ display:'flex', gap:10, flexWrap:'wrap' }}>
          {pill('#21262d','#e6edf3', `TOTAL: ${counts.total}`)}
          {pill('#1a3428','#3fb950', `SUCCESS: ${counts.success}`)}
          {pill('#3d1a18','#f85149', `FAILED: ${counts.failed}`)}
          {pill('#2a1a40','#bc8cff', `PARTIAL: ${counts.partial}`)}
          {pill('#1c2a3a','#58a6ff', `RUNNING: ${counts.running}`)}
        </div>

        {/* Table */}
        <div style={{ background:'#161b22', border:'1px solid #30363d', borderRadius:12, overflow:'hidden' }}>
          <table style={{ width:'100%', borderCollapse:'collapse' }}>
            <thead>
              <tr>{['#','Target','DB','Type','Status','Destinations','Size','Started At','Duration','Logs'].map(h=>(
                <th key={h} style={th}>{h}</th>
              ))}</tr>
            </thead>
            <tbody>
              {loading
                ? <tr><td colSpan={10} style={{ textAlign:'center', padding:40, color:'#6e7681' }}>Loading...</td></tr>
                : runs.length === 0
                ? <tr><td colSpan={10} style={{ textAlign:'center', padding:40, color:'#6e7681' }}>No runs found</td></tr>
                : runs.map(r => {
                    const dur = r.completed_at
                      ? Math.round((new Date(r.completed_at)-new Date(r.started_at))/1000)+'s' : '—';
                    return (
                      <tr key={r.id}
                        onMouseEnter={e=>e.currentTarget.style.background='#1c2128'}
                        onMouseLeave={e=>e.currentTarget.style.background=''}>
                        <td style={td({ color:'#6e7681', fontFamily:'monospace' })}>#{r.id}</td>
                        <td style={td()}><strong>{r.target_name}</strong></td>
                        <td style={td()}><Badge type={r.db_type} small>{r.db_type?.toUpperCase()}</Badge></td>
                        <td style={td({ color:'#8b949e' })}>{r.backup_type}</td>
                        <td style={td()}><Badge type={r.status}>{r.status?.toUpperCase()}</Badge></td>
                        <td style={td()}><DestIcons transfers={r.transfers}/></td>
                        <td style={td({ color:'#8b949e' })}>{fmtBytes(r.file_size_bytes)}</td>
                        <td style={td({ fontSize:11, color:'#8b949e', whiteSpace:'nowrap' })}>
                          {format(new Date(r.started_at), 'dd MMM, hh:mm a')}
                        </td>
                        <td style={td({ color:'#8b949e' })}>{dur}</td>
                        <td style={td()}>
                          <Btn variant="ghost" size="sm"
                            onClick={()=>navigate(`/live-logs?run=${r.id}`)}>Logs</Btn>
                        </td>
                      </tr>
                    );
                  })
              }
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

// ── LIVE LOGS ─────────────────────────────────────────────────────────────────
function levelColor(l) {
  return { INFO:'#58a6ff', SUCCESS:'#3fb950', WARN:'#e3b341', ERROR:'#f85149', DEBUG:'#6e7681' }[l]||'#8b949e';
}

export function LiveLogsPage() {
  const [recentRuns, setRecentRuns] = useState([]);
  const [selectedRun, setSelectedRun] = useState(null);
  const [logs,        setLogs]        = useState([]);
  const [liveLines,   setLiveLines]   = useState([]);
  const [filter,      setFilter]      = useState('');
  const [autoScroll,  setAutoScroll]  = useState(true);
  const [levelFilter, setLevelFilter] = useState('ALL');
  const logRef = useRef(null);
  const [params]  = useSearchParams();

  const onWsMessage = useCallback(msg => {
    if (msg.type==='log' && selectedRun && msg.runId===selectedRun.id) {
      setLiveLines(p=>[...p, { log_level:msg.level, message:msg.message, logged_at:msg.time }]);
    }
    if (msg.type==='run_started') loadRecent();
  }, [selectedRun]);

  const { connected } = useWS();
  useWSMessages(onWsMessage);

  const loadRecent = useCallback(async () => {
    try { setRecentRuns(await runsAPI.list({ limit:10 })); } catch {}
  }, []);

  async function selectRun(run) {
    setSelectedRun(run); setLiveLines([]);
    try { setLogs(await runsAPI.logs(run.id)); } catch(e){ toast(e.message,'error'); }
  }

  useEffect(() => { loadRecent(); }, [loadRecent]);

  useEffect(() => {
    const runId = params.get('run');
    if (runId && recentRuns.length > 0) {
      const r = recentRuns.find(r=>String(r.id)===runId);
      if (r) selectRun(r);
    }
  }, [params, recentRuns]);

  useEffect(() => {
    if (autoScroll && logRef.current)
      logRef.current.scrollTop = logRef.current.scrollHeight;
  }, [logs, liveLines, autoScroll]);

  const allLines = [...logs, ...liveLines];
  const visible  = allLines.filter(l => {
    if (levelFilter!=='ALL' && l.log_level!==levelFilter) return false;
    if (filter && !l.message.toLowerCase().includes(filter.toLowerCase())) return false;
    return true;
  });
  const counts = { INFO:0, SUCCESS:0, WARN:0, ERROR:0 };
  allLines.forEach(l=>{ if(counts[l.log_level]!==undefined) counts[l.log_level]++; });

  return (
    <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>
      <div style={{ padding:'18px 24px 14px', borderBottom:'1px solid #30363d', background:'#161b22', flexShrink:0 }}>
        <div style={{ fontSize:20, fontWeight:500, color:'#e6edf3' }}>Live Log Viewer</div>
        <div style={{ fontSize:12, color:'#8b949e', marginTop:3 }}>
          Real-time backup logs via WebSocket ·{' '}
          <span style={{ color: connected ? '#3fb950' : '#f85149' }}>
            {connected ? '● Connected' : '○ Reconnecting...'}
          </span>
        </div>
      </div>

      <div style={{ flex:1, display:'flex', gap:12, padding:'14px 24px', overflow:'hidden', minHeight:0 }}>
        {/* Run list */}
        <div style={{ width:210, flexShrink:0, display:'flex', flexDirection:'column', gap:5, overflowY:'auto' }}>
          <div style={{ fontSize:10, fontWeight:600, color:'#6e7681', letterSpacing:'.1em',
            textTransform:'uppercase', padding:'2px 4px', marginBottom:4 }}>Recent runs</div>
          {recentRuns.map(r=>(
            <div key={r.id} onClick={()=>selectRun(r)} style={{
              background: selectedRun?.id===r.id ? '#1c2128' : '#161b22',
              border:`1px solid ${selectedRun?.id===r.id ? '#58a6ff' : '#30363d'}`,
              borderRadius:8, padding:'9px 12px', cursor:'pointer',
            }}>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:3 }}>
                <span style={{ fontSize:11, fontWeight:600, color:'#e6edf3' }}>#{r.id}</span>
                <Badge type={r.status} small>{r.status?.toUpperCase()}</Badge>
              </div>
              <div style={{ fontSize:12, fontWeight:500, color:'#e6edf3' }}>{r.target_name}</div>
              <div style={{ fontSize:10, color:'#6e7681', marginTop:2 }}>
                {format(new Date(r.started_at),'hh:mm a')} · {r.backup_type}
              </div>
            </div>
          ))}
          {recentRuns.length===0 && <div style={{ color:'#6e7681', fontSize:12, padding:8 }}>No recent runs</div>}
        </div>

        {/* Log panel */}
        <div style={{ flex:1, background:'#161b22', border:'1px solid #30363d', borderRadius:12,
          display:'flex', flexDirection:'column', minHeight:0 }}>

          {/* Panel header */}
          <div style={{ padding:'10px 16px', borderBottom:'1px solid #30363d', display:'flex',
            alignItems:'center', gap:10, flexShrink:0, flexWrap:'wrap' }}>
            {selectedRun ? (
              <>
                <span style={{ fontSize:14, fontWeight:500, color:'#e6edf3', flex:1 }}>{selectedRun.target_name}</span>
                <span style={{ fontSize:11, color:'#6e7681' }}>{selectedRun.backup_type} · {selectedRun.trigger_type}</span>
                <Badge type={selectedRun.status}>{selectedRun.status?.toUpperCase()}</Badge>
              </>
            ) : (
              <span style={{ fontSize:13, color:'#6e7681' }}>Select a run from the left panel</span>
            )}
            <input value={filter} onChange={e=>setFilter(e.target.value)}
              placeholder="Filter logs..."
              style={{ width:170, fontSize:12, background:'#21262d',
                border:'1px solid #444c56', color:'#e6edf3', borderRadius:8, padding:'5px 10px' }}/>
            <select value={levelFilter} onChange={e=>setLevelFilter(e.target.value)}
              style={{ fontSize:12, background:'#21262d', border:'1px solid #444c56',
                color:'#e6edf3', borderRadius:8, padding:'5px 8px' }}>
              {['ALL','INFO','SUCCESS','WARN','ERROR'].map(l=><option key={l}>{l}</option>)}
            </select>
            <label style={{ display:'flex', alignItems:'center', gap:5, fontSize:12,
              color:'#8b949e', cursor:'pointer' }}>
              <input type="checkbox" checked={autoScroll}
                onChange={e=>setAutoScroll(e.target.checked)}
                style={{ accentColor:'#58a6ff' }}/>
              Auto-scroll
            </label>
            <Btn variant="ghost" size="sm" icon="refresh"
              onClick={()=>selectedRun && selectRun(selectedRun)}>Reload</Btn>
          </div>

          {/* Log body */}
          <div ref={logRef} style={{ flex:1, overflowY:'auto', padding:'10px 16px',
            fontFamily:"'Consolas','Monaco',monospace", fontSize:11.5, lineHeight:1.7 }}>
            {visible.map((l,i)=>(
              <div key={i} style={{ display:'flex', gap:12 }}>
                <span style={{ color:'#6e7681', flexShrink:0, width:52 }}>
                  {format(new Date(l.logged_at),'HH:mm:ss')}
                </span>
                <span style={{ flexShrink:0, width:72, color:levelColor(l.log_level), fontWeight:600 }}>
                  [{l.log_level}]
                </span>
                <span style={{ color: l.log_level==='SUCCESS'?'#3fb950':l.log_level==='ERROR'?'#f85149':'#e6edf3', flex:1 }}>
                  {l.message}
                </span>
              </div>
            ))}
            {!selectedRun && (
              <div style={{ color:'#6e7681', textAlign:'center', padding:40 }}>
                Select a run to view logs
              </div>
            )}
            {selectedRun && visible.length===0 && (
              <div style={{ color:'#6e7681', textAlign:'center', padding:32 }}>
                No log lines match filter
              </div>
            )}
          </div>

          {/* Footer */}
          <div style={{ padding:'6px 16px', borderTop:'1px solid #30363d', display:'flex',
            justifyContent:'space-between', fontSize:11, color:'#6e7681', flexShrink:0 }}>
            <span>{visible.length} lines shown ({allLines.length} total)</span>
            <span>
              <span style={{ color:'#58a6ff', marginRight:10 }}>INFO: {counts.INFO}</span>
              <span style={{ color:'#3fb950', marginRight:10 }}>SUCCESS: {counts.SUCCESS}</span>
              <span style={{ color:'#e3b341', marginRight:10 }}>WARN: {counts.WARN}</span>
              <span style={{ color:'#f85149' }}>ERROR: {counts.ERROR}</span>
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
